const items = $input.all();

return items.map(item => {
  const body = item.json.body || item.json;

  // Contrato en camelCase (con fallback de seguridad)
  const destinatario = body.correo || body.email;
  const nombre = body.nombre || 'Usuario';
  const codigo = body.codigoVerificacion || body.codigo_verificacion;
  const expira = body.expiraEnMinutos || body.expira_en_minutos || 15;
  const usuarioId = body.usuarioId || body.usuario_id;

  const htmlTemplate = `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
</head>
<body style="margin:0;padding:24px;background-color:#0b0f0d;font-family:'Plus Jakarta Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#f1f5f9;">
  <div style="max-width:520px;margin:0 auto;background:#111815;border:1px solid #1f2c25;border-radius:16px;padding:32px;">
    <span style="display:inline-block;background:rgba(201,239,117,0.12);color:#c9ef75;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:1.5px;padding:6px 14px;border-radius:9999px;margin-bottom:16px;">Seguridad</span>
    <h1 style="font-size:22px;color:#ffffff;margin:0 0 12px 0;">Verifica tu cuenta</h1>
    <p style="font-size:14px;color:#cbd5e1;margin:0 0 12px 0;">Hola <strong>${nombre}</strong>,</p>
    <p style="font-size:14px;color:#94a3b8;line-height:1.6;margin:0;">Ingresa este código en la plataforma para completar tu registro. Vence en <strong style="color:#cbd5e1;">${expira} minutos</strong>:</p>
    <div style="background:#0b0f0d;border:1px solid #1f2c25;color:#c9ef75;font-size:32px;font-weight:800;letter-spacing:8px;text-align:center;padding:18px;border-radius:12px;margin:24px 0;">${codigo}</div>
    <p style="font-size:13px;color:#64748b;margin:0;">Si no solicitaste este registro, puedes ignorar este mensaje.</p>
    <p style="font-size:11px;color:#475569;text-align:center;margin:24px 0 0 0;letter-spacing:1px;">AKROS CLUB &middot; ATHLETIC &amp; WELLNESS CLUB</p>
  </div>
</body>
</html>`;

  return {
    json: {
      destinatario: destinatario,
      asunto: `${codigo} es tu código de verificación`,
      html: htmlTemplate,
      usuarioId: usuarioId
    }
  };
});
